  "India's most intelligent property search platform — powered by AI, built for every Indian language.": {
    en: "India's most intelligent property search platform — powered by AI, built for every Indian language.",
    hi: "भारत का सबसे बुद्धिमान प्रॉपर्टी सर्च प्लेटफॉर्म — AI द्वारा संचालित, प्रत्येक भारतीय भाषा के लिए निर्मित।",
    mr: "भारतातील सर्वात बुद्धिमान मालमत्ता शोध प्लॅटफॉर्म — AI द्वारे समर्थित, प्रत्येक भारतीय भाषेसाठी तयार.",
    gu: "ભારતનું સૌથી બુદ્ધિશાળી પ્રોપર્ટી સર્ચ પ્લેટફોર્મ — AI દ્વારા સંચાલિત, દરેક ભારતીય ભાષા માટે નિર્મિત.",
    ta: "இந்தியாவின் புத்திசாலித்தனமான சொத்துத் தேடல் தளம் — AI மூலம் இயக்கப்படுகிறது, ஒவ்வொரு இந்திய மொழிக்கும் உருவாக்கப்பட்டது.",
    te: "భారతదేశపు అత్యంత తెలివైన ప్రాపర్టీ సెర్చ్ ప్లాట్‌ఫారమ్ — AI ద్వారా ఆధారితం, ప్రతి భారతీయ భాష కోసం నిర్మించబడింది.",
    kn: "ಭಾರತದ ಅತ್ಯಂತ ಬುದ್ಧಿವಂತ ಆಸ್ತಿ ಹುಡುಕಾಟ ವೇದಿಕೆ — AI ನಿಂದ ಚಾಲಿತ, ಪ್ರತಿಯೊಂದು ಭಾರತೀಯ ಭಾಷೆಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ.",
    bn: "ভারতের সবচেয়ে বুদ্ধিমান রিয়েল এস্টেট প্ল্যাটফর্ম — AI দ্বারা চালিত, প্রতিটি ভারতীয় ভাষার জন্য নির্মিত।",
  },
  "India's most intelligent property discovery platform. Find your dream home through AI-powered conversational search in 8 languages.": {
    en: "India's most intelligent property discovery platform. Find your dream home through AI-powered conversational search in 8 languages.",
    hi: "भारत का सबसे बुद्धिमान प्रॉपर्टी डिस्कवरी प्लेटफॉर्म। 8 भाषाओं में AI संवादात्मक खोज द्वारा अपना सपनों का घर खोजें।",
    mr: "भारतातील सर्वात बुद्धिमान मालमत्ता शोध प्लॅटफॉर्म. 8 भाषांमध्ये AI द्वारे आपल्या स्वप्नातील घर शोधा.",
    gu: "ભારતનું સૌથી બુદ્ધિશાળી પ્રોપર્ટી ડિસ્કવરી પ્લેટફોર્મ. 8 ભાષાઓમાં AI કન્વર્ઝેશનલ સર્ચ વડે તમારા સપનાનું ઘર શોધો.",
    ta: "இந்தியாவின் மிகவும் புத்திசாலித்தனமான சொத்துக் கண்டுபிடிப்பு தளம். 8 மொழிகளில் AI மூலம் உங்கள் கனவு இல்லத்தைக் கண்டறியவும்.",
    te: "భారతదేశపు అత్యంత తెలివైన ప్రాపర్టీ ప్లాట్‌ఫారమ్. 8 భాషలలో AI సంభాషణ శోధన ద్వారా మీ కలల గృహాన్ని కనుగొనండి.",
    kn: "ಭಾರತದ ಅತ್ಯಂತ ಬುದ್ಧಿವಂತ ಆಸ್ತಿ ಶೋಧ ವೇದಿಕೆ. 8 ಭಾಷೆಗಳಲ್ಲಿ AI ಸಂಭಾಷಣಾ ಹುಡುಕಾಟದ ಮೂಲಕ ನಿಮ್ಮ ಕನಸಿನ ಮನೆಯನ್ನು ಹುಡುಕಿ.",
    bn: "ভারতের সবচেয়ে বুদ্ধিমান প্রপার্টি প্ল্যাটফর্ম। ৮টি ভাষায় AI কথোপকথন অনুসন্ধানের মাধ্যমে আপনার স্বপ্নের বাড়ি খুঁজুন।",
  },
