// Merge MASTER_VOCABULARY into PHRASE_DICTIONARY
for (const [k, v] of Object.entries(MASTER_VOCABULARY)) {
  if (!PHRASE_DICTIONARY[k]) {
    PHRASE_DICTIONARY[k] = v;
  }
}

// Populate dictionary with all phrases from TRANSLATIONS
for (const key of Object.keys(TRANSLATIONS.en)) {
  const enVal = (TRANSLATIONS.en as any)[key];
  if (typeof enVal === "string" && enVal.trim().length > 0) {
    const trimmed = enVal.trim();
    if (!PHRASE_DICTIONARY[trimmed]) {
      PHRASE_DICTIONARY[trimmed] = {
        en: trimmed,
        hi: ((TRANSLATIONS.hi as any)[key] || trimmed).trim(),
        mr: ((TRANSLATIONS.mr as any)[key] || trimmed).trim(),
        gu: ((TRANSLATIONS.gu as any)[key] || trimmed).trim(),
        ta: ((TRANSLATIONS.ta as any)[key] || trimmed).trim(),
        te: ((TRANSLATIONS.te as any)[key] || trimmed).trim(),
        kn: ((TRANSLATIONS.kn as any)[key] || trimmed).trim(),
        bn: ((TRANSLATIONS.bn as any)[key] || trimmed).trim(),
      };
    }
  }
}

// Build reverse lookup from any translated or canonical phrase back to the canonical English phrase
const REVERSE_LOOKUP: Map<string, string> = new Map();
function rebuildReverseLookup() {
  REVERSE_LOOKUP.clear();
  for (const [canonical, translations] of Object.entries(PHRASE_DICTIONARY)) {
    REVERSE_LOOKUP.set(canonical.trim().toLowerCase(), canonical);
    for (const val of Object.values(translations)) {
      if (val && typeof val === "string") {
        REVERSE_LOOKUP.set(val.trim().toLowerCase(), canonical);
      }
    }
  }
}
rebuildReverseLookup();

