// Word lookup map for lightning-fast O(1) single-word translation
export const WORD_LOOKUP: Map<string, PhraseTranslations> = new Map();

export function rebuildWordLookup() {
  WORD_LOOKUP.clear();

  // 1. Populate from MASTER_WORD_DICTIONARY
  for (const [k, v] of Object.entries(MASTER_WORD_DICTIONARY)) {
    WORD_LOOKUP.set(k.trim().toLowerCase(), v);
  }

  // 2. Populate single-word entries from MASTER_VOCABULARY
  for (const [k, v] of Object.entries(MASTER_VOCABULARY)) {
    const trimmed = k.trim().toLowerCase();
    if (!trimmed.includes(" ") && !WORD_LOOKUP.has(trimmed)) {
      WORD_LOOKUP.set(trimmed, v);
    }
  }

  // 3. Populate single-word entries from PHRASE_DICTIONARY
  for (const [k, v] of Object.entries(PHRASE_DICTIONARY)) {
    const trimmed = k.trim().toLowerCase();
    if (!trimmed.includes(" ") && !WORD_LOOKUP.has(trimmed)) {
      WORD_LOOKUP.set(trimmed, v);
    }
  }
}
rebuildWordLookup();

/**
 * Translates an individual English word into the target language.
 * Searches MASTER_WORD_DICTIONARY, PHRASE_DICTIONARY, and stem variations.
 */
export function translateWord(rawWord: string, targetLang: LangCode | string): string {
  if (!rawWord || targetLang === "en") return rawWord;
  const lang = (targetLang as LangCode) || "en";
  const trimmed = rawWord.trim();
  if (!trimmed) return rawWord;

  // Never translate brand identity "SAI"
  if (trimmed.toUpperCase() === "SAI") return rawWord;

  // If already non-Latin (Devanagari, Tamil, Telugu, Kannada, Bengali, etc.), return as is
  if (!/[a-zA-Z]/.test(trimmed)) return rawWord;

  const lower = trimmed.toLowerCase();

  // 1. Direct word dictionary lookup
  const wordEntry = WORD_LOOKUP.get(lower);
  if (wordEntry && wordEntry[lang]) {
    return wordEntry[lang];
  }

  // 2. Direct phrase dictionary lookup
  const canonical = REVERSE_LOOKUP.get(lower);
  if (canonical && PHRASE_DICTIONARY[canonical] && PHRASE_DICTIONARY[canonical][lang]) {
    return PHRASE_DICTIONARY[canonical][lang];
  }

  // 3. Stem variations (plurals -s, -es, -ies; progressive -ing; past -ed)
  if (lower.endsWith("ies") && lower.length > 4) {
    const stem = lower.slice(0, -3) + "y";
    const stemEntry = WORD_LOOKUP.get(stem);
    if (stemEntry && stemEntry[lang]) return stemEntry[lang];
  }
  if (lower.endsWith("es") && lower.length > 3) {
    const stem = lower.slice(0, -2);
    const stemEntry = WORD_LOOKUP.get(stem);
    if (stemEntry && stemEntry[lang]) return stemEntry[lang];
  }
  if (lower.endsWith("s") && lower.length > 2 && !lower.endsWith("ss")) {
    const stem = lower.slice(0, -1);
    const stemEntry = WORD_LOOKUP.get(stem);
    if (stemEntry && stemEntry[lang]) return stemEntry[lang];
  }
  if (lower.endsWith("ing") && lower.length > 4) {
    const stem = lower.slice(0, -3);
    const stemEntry = WORD_LOOKUP.get(stem);
    if (stemEntry && stemEntry[lang]) return stemEntry[lang];
  }
  if (lower.endsWith("ed") && lower.length > 3) {
    const stem = lower.slice(0, -2);
    const stemEntry = WORD_LOOKUP.get(stem);
    if (stemEntry && stemEntry[lang]) return stemEntry[lang];
  }

  return rawWord;
}

/**
 * Converts text word-by-word into the target language.
 * Tokenizes text, preserving whitespace, punctuation, numbers, and symbols,
 * and converts every English word to the target language.
 */
export function convertWordToWord(text: string, targetLang: LangCode | string): string {
  if (!text || targetLang === "en") return text;
  const lang = (targetLang as LangCode) || "en";

  // Check if text has Latin letters to translate
  if (!/[a-zA-Z]/.test(text)) return text;

  // Match sequences of word chars (including apostrophes within words)
  return text.replace(/\b[a-zA-Z]+(?:'[a-zA-Z]+)?\b/g, (match) => {
    return translateWord(match, lang);
  });
}

const SORTED_PHRASE_KEYS = Object.keys(PHRASE_DICTIONARY).sort((a, b) => b.length - a.length);

let activeObserver: MutationObserver | null = null;
let currentActiveLang: LangCode = "en";

/**
 * Translates a single text string into the target language.
 * Multi-pass pipeline: exact lookup -> pattern templates -> greedy subphrase token replacement.
 */
export function translateText(rawText: string, targetLang: LangCode | string): string {
  if (!rawText || targetLang === "en") return rawText;
  const lang = (targetLang as LangCode) || "en";
  const trimmed = rawText.trim();
  if (!trimmed) return rawText;

  // 1. Direct exact lookup
  const canonical = REVERSE_LOOKUP.get(trimmed.toLowerCase());
  if (canonical && PHRASE_DICTIONARY[canonical]) {
    const translated = PHRASE_DICTIONARY[canonical][lang];
    if (translated) {
      const leadingSpace = rawText.match(/^\s*/)?.[0] || "";
      const trailingSpace = rawText.match(/\s*$/)?.[0] || "";
      return leadingSpace + translated + trailingSpace;
    }
  }

  // 2. Normalized lookup: strip and re-attach surrounding symbols/arrows/punctuation
  const matchPunct = trimmed.match(/^([^a-zA-Z0-9\u0900-\u0D7F]*)(.*?)([^a-zA-Z0-9\u0900-\u0D7F]*)$/);
  if (matchPunct) {
    const prefix = matchPunct[1] || "";
    const core = (matchPunct[2] || "").trim();
    const suffix = matchPunct[3] || "";
    if (core && core.length > 0) {
      const coreCanonical = REVERSE_LOOKUP.get(core.toLowerCase());
      if (coreCanonical && PHRASE_DICTIONARY[coreCanonical]) {
        const transCore = PHRASE_DICTIONARY[coreCanonical][lang];
        if (transCore) {
          const leadingSpace = rawText.match(/^\s*/)?.[0] || "";
          const trailingSpace = rawText.match(/\s*$/)?.[0] || "";
          return leadingSpace + prefix + transCore + suffix + trailingSpace;
        }
      }
    }
  }

  // 3. Dynamic pattern: "Continue in [Language]"
  const continueMatch = trimmed.match(/^Continue in (.+)$/i);
  if (continueMatch) {
    const langName = continueMatch[1].trim();
    const continueLabels: Record<LangCode, string> = {
      en: `Continue in ${langName}`,
      hi: `${langName} में आगे बढ़ें`,
      mr: `${langName} मध्ये पुढे जा`,
      gu: `${langName} માં આગળ વધો`,
      ta: `${langName} இல் தொடர்க`,
      te: `${langName} లో కొనసాగించండి`,
      kn: `${langName} ನಲ್ಲಿ ಮುಂದುವರಿಯಿರಿ`,
      bn: `${langName} তে এগিয়ে যান`,
    };
    return continueLabels[lang] || rawText;
  }

  // 4. Dynamic pattern: Copyright notice
  if (trimmed.includes("SAI — Smart AI Property Finder. All rights reserved.")) {
    const crLabels: Record<LangCode, string> = {
      en: "© 2025 SAI — Smart AI Property Finder. All rights reserved.",
      hi: "© 2025 SAI — स्मार्ट AI प्रॉपर्टी फाइंडर। सर्वाधिकार सुरक्षित।",
      mr: "© 2025 SAI — स्मार्ट AI मालमत्ता शोधक. सर्व हक्क राखीव.",
      gu: "© 2025 SAI — સ્માર્ટ AI પ્રોપર્ટી ફાઇન્ડર. બધા હકો સુરક્ષિત.",
      ta: "© 2025 SAI — ஸ்மார்ட் AI சொத்து கண்டுபிடிப்பு. அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.",
      te: "© 2025 SAI — స్మార్ట్ AI ప్రాపర్టీ ఫైండర్. అన్ని హక్కులు ప్రత్యేకించబడ్డాయి.",
      kn: "© 2025 SAI — ಸ್ಮಾರ್ಟ್ AI ಆಸ್ತಿ ಹುಡುಕಾಟ. ಎಲ್ಲಾ ಹಕ್ಕುಗಳನ್ನು ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ.",
      bn: "© 2025 SAI — স্মার্ট AI প্রপার্টি ফাইন্ডার। সর্বস্বত্ব সংরক্ষিত।",
    };
    return crLabels[lang] || rawText;
  }

  // 5. Dynamic regex pattern: "Properties in [City]" / "Flats in [City]"
  const propInCityMatch = trimmed.match(/^(Properties|Flats|Apartments|Villas|Plots|Homes|Houses)\s+in\s+([A-Za-z\s]+)$/i);
  if (propInCityMatch) {
    const pType = propInCityMatch[1];
    const city = propInCityMatch[2].trim();
    const transPType = PHRASE_DICTIONARY[pType]?.[lang] || pType;
    const transCity = PHRASE_DICTIONARY[city]?.[lang] || city;
    const inTemplates: Record<LangCode, (c: string, p: string) => string> = {
      en: (c, p) => `${p} in ${c}`,
      hi: (c, p) => `${c} में ${p}`,
      mr: (c, p) => `${c} मधील ${p}`,
      gu: (c, p) => `${c}માં ${p}`,
      ta: (c, p) => `${c} இல் ${p}`,
      te: (c, p) => `${c} లో ${p}`,
      kn: (c, p) => `${c} ನಲ್ಲಿ ${p}`,
      bn: (c, p) => `${c} এ ${p}`,
    };
    return inTemplates[lang](transCity, transPType);
  }

  // 6. Dynamic regex pattern: "[N] BHK Flat in [Locality]" / "[N] BHK in [Locality]"
  const bhkInLocMatch = trimmed.match(/^(\d+)\s*(?:BHK|bhk)\s*(Flat|Apartment|Villa)?\s*(?:in|at)?\s*([A-Za-z\s]+)$/i);
  if (bhkInLocMatch) {
    const num = bhkInLocMatch[1];
    const type = bhkInLocMatch[2] ? (PHRASE_DICTIONARY[bhkInLocMatch[2]]?.[lang] || bhkInLocMatch[2]) : "";
    const loc = bhkInLocMatch[3]?.trim();
    const transLoc = PHRASE_DICTIONARY[loc]?.[lang] || loc;
    const transBhk = PHRASE_DICTIONARY["BHK"]?.[lang] || "BHK";
    const bhkTemplates: Record<LangCode, string> = {
      en: `${num} BHK ${type} in ${transLoc}`.replace(/\s+/g, " "),
      hi: `${transLoc} में ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      mr: `${transLoc} मधील ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      gu: `${transLoc}માં ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      ta: `${transLoc} இல் ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      te: `${transLoc} లో ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      kn: `${transLoc} ನಲ್ಲಿ ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
      bn: `${transLoc} এ ${num} ${transBhk} ${type}`.replace(/\s+/g, " "),
    };
    return bhkTemplates[lang];
  }

  // 7. Dynamic regex pattern: "Showing [X] properties in [Location]"
  const showingMatch = trimmed.match(/^Showing\s*(\d+)\s*(?:properties|units|results)?\s*(?:in|at|for)?\s*([A-Za-z\s]+)$/i);
  if (showingMatch) {
    const count = showingMatch[1];
    const loc = showingMatch[2]?.trim();
    const transLoc = PHRASE_DICTIONARY[loc]?.[lang] || loc;
    const transProp = PHRASE_DICTIONARY["Properties"]?.[lang] || "Properties";
    const showTemplates: Record<LangCode, string> = {
      en: `Showing ${count} properties in ${transLoc}`,
      hi: `${transLoc} में ${count} ${transProp} दिखाई जा रही हैं`,
      mr: `${transLoc} मधील ${count} ${transProp} दाखवत आहे`,
      gu: `${transLoc}માં ${count} ${transProp} દર્શાવી રહ્યું છે`,
      ta: `${transLoc} இல் ${count} ${transProp} காண்பிக்கப்படுகின்றன`,
      te: `${transLoc} లో ${count} ${transProp} చూపిస్తోంది`,
      kn: `${transLoc} ನಲ್ಲಿ ${count} ${transProp} ತೋರಿಸಲಾಗುತ್ತಿದೆ`,
      bn: `${transLoc} এ ${count} টি ${transProp} দেখানো হচ্ছে`,
    };
    return showTemplates[lang];
  }

  // 8. Greedy subphrase token replacement
  let replaced = rawText;
  let hasReplaced = false;

  // Handle rates: / month, / mo, / yr, Cr
  replaced = replaced.replace(/\/\s*(month|mo)\b/gi, (match) => {
    hasReplaced = true;
    return PHRASE_DICTIONARY["/ month"]?.[lang] || match;
  });
  replaced = replaced.replace(/\/\s*(year|yr)\b/gi, (match) => {
    hasReplaced = true;
    const yrMap: Record<LangCode, string> = {
      en: "/ yr", hi: "/ वर्ष", mr: "/ वर्ष", gu: "/ વર્ષ", ta: "/ ஆண்டு", te: "/ సంవత్సరం", kn: "/ ವರ್ಷ", bn: "/ বছর"
    };
    return yrMap[lang] || match;
  });
  replaced = replaced.replace(/\bCr\b/g, (match) => {
    hasReplaced = true;
    return PHRASE_DICTIONARY["Cr"]?.[lang] || match;
  });

  for (const phrase of SORTED_PHRASE_KEYS) {
    if (phrase.length < 3) continue;
    // Never translate brand identity "SAI"
    if (phrase.toUpperCase() === "SAI") continue;

    const targetVal = PHRASE_DICTIONARY[phrase]?.[lang];
    if (!targetVal || targetVal === phrase) continue;

    const escaped = phrase.replace(/[-/\\^$*+?.()|[\]{}]/g, "\\$&");
    const isAlphanumericOnly = /^[a-zA-Z0-9]/.test(phrase) && /[a-zA-Z0-9]$/.test(phrase);

    if (isAlphanumericOnly) {
      const regex = new RegExp(`\\b${escaped}\\b`, "gi");
      if (regex.test(replaced)) {
        replaced = replaced.replace(regex, targetVal);
        hasReplaced = true;
      }
    } else {
      const regex = new RegExp(`(^|[^a-zA-Z0-9])${escaped}(?=[^a-zA-Z0-9]|$)`, "gi");
      if (regex.test(replaced)) {
        replaced = replaced.replace(regex, `$1${targetVal}`);
        hasReplaced = true;
      }
    }
  }

    // 9. Word-to-word conversion: convert any remaining English words into the target language
  const wordConverted = convertWordToWord(replaced, lang);
  if (wordConverted && wordConverted !== rawText) {
    return wordConverted;
  }

  if (hasReplaced) {
    return replaced;
  }

  return rawText;
}

/**
 * Traverses all DOM text nodes, input placeholders, titles, and aria-labels,
 * translating them losslessly in place.
 */
export function translateDomTree(container: Node, targetLang: LangCode | string) {
  if (!container) return;
  const lang = (targetLang as LangCode) || "en";
  const isEnglish = lang === "en";

  // 1. Translate text nodes
  const walker = document.createTreeWalker(
    container,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: (node) => {
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName.toLowerCase();
        if (tag === "script" || tag === "style" || tag === "noscript" || tag === "code" || tag === "svg") {
          return NodeFilter.FILTER_REJECT;
        }
        if (parent.closest(".notranslate") || parent.getAttribute("translate") === "no") {
          return NodeFilter.FILTER_REJECT;
        }
        const text = node.textContent?.trim();
        if (!text || text.length === 0 || /^[\d\s₹$€%+\-.,/\\:;!?()#@*&^~`|[\]{}<>_="'`]+$/.test(text)) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      },
    }
  );

  let currentNode = walker.nextNode() as Text | null;
  while (currentNode) {
    let orig = (currentNode as any).__sai_orig_text__;
    if (orig === undefined) {
      orig = currentNode.textContent || "";
      (currentNode as any).__sai_orig_text__ = orig;
    }

    if (isEnglish) {
      if (currentNode.textContent !== orig) {
        currentNode.textContent = orig;
      }
    } else {
      const translated = translateText(orig, lang);
      if (translated && translated !== currentNode.textContent) {
        currentNode.textContent = translated;
      }
    }

    currentNode = walker.nextNode() as Text | null;
  }

  // 2. Element attributes: placeholder, title, aria-label
  if (container instanceof Element || (typeof Document !== "undefined" && container instanceof Document)) {
    const elContainer = container as Element;

    // Placeholders
    const inputs = elContainer.querySelectorAll("input[placeholder], textarea[placeholder]");
    inputs.forEach((el) => {
      const input = el as HTMLInputElement | HTMLTextAreaElement;
      if (input.closest(".notranslate")) return;
      let origPh = (input as any).__sai_orig_ph__;
      if (origPh === undefined) {
        origPh = input.placeholder;
        (input as any).__sai_orig_ph__ = origPh;
      }
      if (isEnglish) {
        if (input.placeholder !== origPh) input.placeholder = origPh;
      } else {
        const transPh = translateText(origPh, lang);
        if (transPh && transPh !== input.placeholder) input.placeholder = transPh;
      }
    });

    // Titles
    const titled = elContainer.querySelectorAll("[title]");
    titled.forEach((el) => {
      const htmlEl = el as HTMLElement;
      if (htmlEl.closest(".notranslate")) return;
      let origTitle = (htmlEl as any).__sai_orig_title__;
      if (origTitle === undefined) {
        origTitle = htmlEl.title;
        (htmlEl as any).__sai_orig_title__ = origTitle;
      }
      if (isEnglish) {
        if (htmlEl.title !== origTitle) htmlEl.title = origTitle;
      } else {
        const transTitle = translateText(origTitle, lang);
        if (transTitle && transTitle !== htmlEl.title) htmlEl.title = transTitle;
      }
    });

    // Aria Labels
    const ariaLabeled = elContainer.querySelectorAll("[aria-label]");
    ariaLabeled.forEach((el) => {
      if (el.closest(".notranslate")) return;
      let origAria = (el as any).__sai_orig_aria__;
      if (origAria === undefined) {
        origAria = el.getAttribute("aria-label") || "";
        (el as any).__sai_orig_aria__ = origAria;
      }
      if (isEnglish) {
        if (el.getAttribute("aria-label") !== origAria) el.setAttribute("aria-label", origAria);
      } else {
        const transAria = translateText(origAria, lang);
        if (transAria && transAria !== el.getAttribute("aria-label")) el.setAttribute("aria-label", transAria);
      }
    });
  }
}

/**
 * Converts the entire website into the target language.
 * Connects in-memory DOM translation with automatic mutation observer.
 */
export function convertWholeWebsite(targetLang: LangCode | string) {
  const code = (targetLang as LangCode) || "en";
  currentActiveLang = code;

  // Set document language attribute
  if (typeof document !== "undefined" && document.documentElement) {
    document.documentElement.lang = code;
  }

  // Run DOM tree translation immediately
  if (typeof document !== "undefined") {
    const root = document.getElementById("root") || document.body;
    if (root) {
      translateDomTree(root, code);
    }

    // Restart MutationObserver for dynamic React re-renders
    if (activeObserver) {
      activeObserver.disconnect();
    }

    let isTranslating = false;
    activeObserver = new MutationObserver((mutations) => {
      if (isTranslating) return;
      isTranslating = true;
      requestAnimationFrame(() => {
        for (const m of mutations) {
          if (m.type === "childList") {
            for (const node of Array.from(m.addedNodes)) {
              if (node.nodeType === Node.ELEMENT_NODE || node.nodeType === Node.TEXT_NODE) {
                translateDomTree(node, currentActiveLang);
              }
            }
          } else if (m.type === "characterData" && m.target) {
            const parent = m.target.parentElement;
            if (parent && !parent.closest(".notranslate")) {
              const node = m.target as Text;
              const current = node.textContent || "";
              if (currentActiveLang === "en") {
                node.textContent = current;
                (node as any).__sai_orig_text__ = current;
              } else {
                const orig = (node as any).__sai_orig_text__ || current;
                (node as any).__sai_orig_text__ = orig;
                const trans = translateText(orig, currentActiveLang);
                if (trans !== current) {
                  node.textContent = trans;
                }
              }
            }
          } else if (m.type === "attributes" && m.target instanceof Element) {
            translateDomTree(m.target, currentActiveLang);
          }
        }
        isTranslating = false;
      });
    });

    if (root) {
      activeObserver.observe(root, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ["placeholder", "title", "aria-label"],
      });
    }
  }
}
if (typeof window !== "undefined") {
  (window as any).__sai_translator = {
    convertWholeWebsite,
    translateDomTree,
    translateText,
    convertWordToWord,
    translateWord,
    MASTER_WORD_DICTIONARY,
    WORD_LOOKUP,
    PHRASE_DICTIONARY,
  };
}
